for(const r of roleRows){const cat=localCategories.find(c=>c.slug===r[0]);if(cat&&!localCommands.some(c=>c.slug===r[1]))localCommands.push({id:localCommands.length+1,slug:r[1],name:r[2],syntax:r[3],description:r[4],instruction_template:r[5],example_input:r[6],example_output:r[7],difficulty:r[8],status:'reviewed',tags:r[9],limitations:'Role-specific reusable prompt template. Verify facts, professional standards and local requirements; it does not replace licensed judgment.',category:cat})}

